<script setup>
import {computed,ref} from 'vue'
import DeviceArt from './illustrations/DeviceArt.vue'
import {equipmentArt} from '../data/equipmentPresentation'
import SvgIcon from './ui/SvgIcon.vue'
import Button from './ui/Button.vue'
import {shortDate} from '../data/admin'
const props=defineProps({requests:{type:Array,default:()=>[]}})
const scope=ref('all')
const manual=computed(()=>props.requests.filter(r=>r.needs_manual_review))
const fresh=computed(()=>props.requests.filter(r=>r.status==='new'&&!r.needs_manual_review))
const tabs=computed(()=>[{key:'all',label:'Вся очередь',count:props.requests.length},{key:'manual',label:'Ручная проверка',count:manual.value.length},{key:'new',label:'Новые',count:fresh.value.length}])
const rows=computed(()=>props.requests.filter(r=>scope.value==='all'||(scope.value==='manual'?r.needs_manual_review:r.status==='new'&&!r.needs_manual_review)).slice().sort((a,b)=>Number(!!b.needs_manual_review)-Number(!!a.needs_manual_review)||a.created_at.localeCompare(b.created_at)||a.id-b.id).slice(0,4))
</script>
<template><section class="attention-queue"><header><div><span class="admin-visual-eyebrow">ОЧЕРЕДЬ РЕШЕНИЙ</span><h2>Требуют внимания <span>{{requests.length}}</span></h2><p>Ручная проверка — в начале. Затем ранние обращения.</p></div><span class="attention-header-art"><SvgIcon name="clipboard" :size="25"/></span></header><div class="attention-tabs" aria-label="Тип обращения"><button v-for="tab in tabs" :key="tab.key" :aria-pressed="scope===tab.key" @click="scope=tab.key" type="button">{{tab.label}}<span>{{tab.count}}</span></button></div><div class="attention-items"><RouterLink v-for="r in rows" :key="r.id" :to="'/admin/requests?request='+r.id" class="attention-item"><span class="attention-device"><DeviceArt :name="equipmentArt(r.service?.equipment_category)"/></span><div class="attention-item-copy"><div><span class="attention-number">{{r.request_number}}</span><span class="attention-kind" :class="{manual:r.needs_manual_review}">{{r.needs_manual_review?'Проверка':'Новая'}}</span></div><h3>{{r.service?.name}}</h3><p>{{r.client?.full_name}} · {{shortDate(r.created_at)}}</p><span class="attention-next">{{r.needs_manual_review?'Уточнить детали и связаться с клиентом':'Проверить данные и подтвердить'}}<SvgIcon name="arrowRight" :size="13"/></span></div></RouterLink><div v-if="!rows.length" class="attention-empty"><SvgIcon name="checkCircle" :size="28"/><h3>Всё разобрано</h3><p>В этой категории нет обращений.</p></div></div><footer><span>Показано {{rows.length}} из {{scope==='all'?requests.length:scope==='manual'?manual.length:fresh.length}}</span><Button variant="ghost" size="sm" to="/admin/requests?attention=1">Вся очередь <SvgIcon name="arrowRight" :size="14"/></Button></footer></section></template>
<style scoped>.attention-queue{border:1px solid var(--border);border-radius:21px;overflow:hidden;background:radial-gradient(ellipse at 95% 0,color-mix(in srgb,var(--amber) 7%,transparent),transparent 50%),var(--surface);display:flex;flex-direction:column}.attention-queue>header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:24px 24px 18px}.attention-queue h2{font-size:21px;font-weight:730;letter-spacing:-.03em;margin-top:8px;display:flex;align-items:center;gap:10px}.attention-queue h2>span{font-size:12px;letter-spacing:0;color:var(--amber);border:1px solid color-mix(in srgb,var(--amber) 22%,var(--border));background:color-mix(in srgb,var(--amber) 10%,transparent);border-radius:8px;padding:4px 7px}.attention-queue header p{font-size:12px;line-height:1.7;color:var(--muted);margin-top:7px}.attention-header-art{display:grid;place-items:center;width:47px;height:47px;border-radius:15px;background:color-mix(in srgb,var(--amber) 10%,var(--surface));color:var(--amber);flex-shrink:0;border:1px solid color-mix(in srgb,var(--amber) 18%,var(--border));transform:rotate(6deg)}.attention-tabs{display:flex;flex-wrap:wrap;gap:6px;padding:0 24px 18px}.attention-tabs button{display:flex;align-items:center;gap:7px;border:1px solid var(--border);border-radius:9px;padding:7px 9px;color:var(--muted);font-size:11px;cursor:pointer;background:var(--surface)}.attention-tabs button[aria-pressed=true]{color:var(--blue);border-color:color-mix(in srgb,var(--blue) 30%,var(--border));background:color-mix(in srgb,var(--blue) 6%,var(--surface))}.attention-tabs button>span{font-size:10px;font-weight:750}.attention-items{display:grid;gap:9px;padding:0 16px 16px;flex:1;align-content:start}.attention-item{display:flex;gap:12px;padding:14px;border:1px solid var(--border);border-radius:14px;background:var(--bg);transition:border-color .2s,transform .2s}.attention-item:hover{border-color:color-mix(in srgb,var(--blue) 45%,var(--border));transform:translateX(2px)}.attention-device{display:block;width:46px;height:46px;flex-shrink:0;padding:3px;border:1px solid var(--border);border-radius:12px;background:var(--surface)}.attention-item-copy{min-width:0;flex:1}.attention-item-copy>div{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}.attention-number{font-size:10px;letter-spacing:.03em;color:var(--muted);font-family:ui-monospace,monospace}.attention-kind{font-size:10px;padding:3px 7px;border-radius:6px;background:color-mix(in srgb,var(--blue) 9%,transparent);color:var(--blue);font-weight:600}.attention-kind.manual{background:color-mix(in srgb,var(--amber) 12%,transparent);color:var(--amber)}.attention-item h3{font-size:14px;font-weight:650;line-height:1.5;margin-top:7px}.attention-item p{font-size:12px;color:var(--muted);line-height:1.6;margin-top:3px}.attention-next{display:flex;align-items:center;gap:6px;font-size:11px;color:var(--blue);margin-top:10px;line-height:1.5}.attention-next svg{flex-shrink:0}.attention-queue footer{display:flex;align-items:center;justify-content:space-between;gap:10px;border-top:1px solid var(--border);padding:12px 18px}.attention-queue footer>span{font-size:11px;color:var(--muted)}.attention-empty{text-align:center;padding:35px 12px;color:var(--green)}.attention-empty svg{margin:auto}.attention-empty h3{margin-top:12px;font-weight:650;color:var(--text)}.attention-empty p{font-size:13px;color:var(--muted);margin-top:7px}@media(max-width:500px){.attention-queue>header{padding:21px 18px 16px}.attention-header-art{display:none}.attention-queue h2{font-size:21px}.attention-tabs{padding-inline:18px}.attention-item{padding:12px;gap:10px}.attention-next{font-size:11px}.attention-device{width:41px;height:41px}.attention-number{font-size:9px}}
</style>
